-- Fixed shared variants and owner-only personal definitions. No numerical snapshot rewrite.
begin;
create function public.exercise_library_normalize(p_name text)returns text language sql immutable set search_path=public,pg_temp as $$select trim(regexp_replace(translate(lower(coalesce(p_name,'')),'àâäáãåçéèêëíìîïñóòôöõúùûüýÿœæ','aaaaaaceeeeiiiinooooouuuuyyoa'),'[^a-z0-9]+',' ','g'))$$;
create table public.common_exercises(id text primary key,definition jsonb not null,signature text not null unique,creator_id uuid references profiles(id)on delete set null,created_at timestamptz not null default now());
create table public.personal_exercises(id text primary key,owner_id uuid not null references profiles(id)on delete cascade,origin_id text,definition jsonb not null,archived boolean not null default false,updated_at timestamptz not null default now());
create index personal_exercises_owner on public.personal_exercises(owner_id,archived);
create table public.exercise_creation_requests(owner_id uuid not null references profiles(id)on delete cascade,request_id text not null,common_id text not null references common_exercises(id),primary key(owner_id,request_id));
create table public.exercise_legacy_references(owner_id uuid not null references profiles(id)on delete cascade,legacy_id text not null,definition_key text not null,library_id text not null,scope text not null check(scope in('common','personal')),primary key(owner_id,legacy_id,definition_key));
alter table public.common_exercises enable row level security;alter table public.personal_exercises enable row level security;alter table public.exercise_creation_requests enable row level security;alter table public.exercise_legacy_references enable row level security;
create policy common_exercises_read on public.common_exercises for select to anon,authenticated using(true);
create policy personal_exercises_read on public.personal_exercises for select to authenticated using(owner_id=auth.uid());
create policy exercise_requests_read on public.exercise_creation_requests for select to authenticated using(owner_id=auth.uid());
create policy exercise_legacy_read on public.exercise_legacy_references for select to authenticated using(owner_id=auth.uid());
revoke all on public.common_exercises,public.personal_exercises,public.exercise_creation_requests,public.exercise_legacy_references from public,anon,authenticated;
grant select(id,definition)on public.common_exercises to anon,authenticated;
grant select on public.personal_exercises,public.exercise_creation_requests,public.exercise_legacy_references to authenticated;

create function public.exercise_definition_signature(p jsonb)returns text language sql immutable set search_path=public,pg_temp as $$select md5(jsonb_build_array(exercise_library_normalize(p->>'name'),p->>'equipment',p->>'measurement')::text)$$;
create function public.exercise_definition_clean(p jsonb)returns jsonb language plpgsql immutable set search_path=public,pg_temp as $$
declare result jsonb;muscle text;begin
 if p is null or jsonb_typeof(p)is distinct from 'object'or length(trim(coalesce(p->>'name','')))not between 1 and 200 or coalesce(p->>'loadMode','')not in('bilateral','unilateral')or coalesce(p->>'measurement','')not in('external_load','bodyweight','added_load','assistance','duration')or length(coalesce(p->>'equipment',''))not between 1 and 80 then raise exception 'INVALID_EXERCISE';end if;
 if jsonb_typeof(p->'muscles'->'primary')is distinct from 'array'or jsonb_typeof(p->'muscles'->'secondary')is distinct from 'array'then raise exception 'INVALID_MUSCLES';end if;
 for muscle in select jsonb_array_elements_text(p->'muscles'->'primary')union all select jsonb_array_elements_text(p->'muscles'->'secondary')loop
 if muscle not in('chest','lats','upper_back','traps','front_delts','side_delts','rear_delts','biceps','triceps','forearms','abs','erectors','quads','hamstrings','glutes','calves','adductors','brachialis','abductors')then raise exception 'INVALID_MUSCLES';end if;end loop;
 if jsonb_array_length(p->'muscles'->'primary')>19 or jsonb_array_length(p->'muscles'->'secondary')>19 then raise exception 'INVALID_MUSCLES';end if;
 if exists(select value from jsonb_array_elements_text(p->'muscles'->'primary')intersect select value from jsonb_array_elements_text(p->'muscles'->'secondary'))then raise exception 'DUPLICATE_MUSCLES';end if;
 result:=jsonb_build_object('name',trim(p->>'name'),'equipment',p->>'equipment','loadMode',p->>'loadMode','measurement',p->>'measurement','muscles',p->'muscles','familyId',left(coalesce(p->>'familyId','custom'),200),'familyLabel',left(coalesce(p->>'familyLabel','Autres exercices'),200),'aliases',case when jsonb_typeof(p->'aliases')='array'and jsonb_array_length(p->'aliases')<=50 then p->'aliases'else '[]'::jsonb end);
 if exists(select 1 from jsonb_array_elements(result->'aliases')a where jsonb_typeof(a)<>'string'or length(a#>>'{}')>200)then raise exception 'INVALID_ALIAS';end if;
 if p->>'measurement'='duration'then result:=result||jsonb_build_object('tracking',case when p->>'tracking'='mobility'then 'mobility'else 'cardio'end,'counter','duration','isometric',coalesce(p->'isometric','false'::jsonb));end if;
 return result;
end$$;
