create function public.exercise_library_shared_match(p jsonb)returns text language plpgsql stable security definer set search_path=public,pg_temp as $$declare chosen text;n integer;begin
 if p->>'libraryScope'='personal'then return null;end if;
 if exists(select 1 from common_exercises where id=p->>'libraryId')then return p->>'libraryId';end if;
 select count(*),min(id)into n,chosen from common_exercises c where
 (coalesce(p->>'equipment','unknown')='unknown'or c.definition->>'equipment'=p->>'equipment'or p->>'tracking'='cardio'and c.definition->>'tracking'='cardio')and
 exists(select 1 from jsonb_array_elements_text(coalesce(c.definition->'legacyNames','[]'::jsonb)||jsonb_build_array(c.definition->>'name'))a where exercise_library_normalize(a)=exercise_library_normalize(p->>'name'))and
 (c.id=p->>'id'or coalesce(c.definition->'legacyIds','[]'::jsonb)?(p->>'id')or coalesce(p->>'equipment','unknown')<>'unknown');
 if n=1 then return chosen;end if;return null;
end$$;
create function public.exercise_library_create(p_id text,p_definition jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare u uuid:=social_uid();d jsonb;row common_exercises;begin
 if p_id is null or length(p_id)not between 1 and 5000 then raise exception 'INVALID_EXERCISE_ID';end if;
 select c.*into row from exercise_creation_requests r join common_exercises c on c.id=r.common_id where r.owner_id=u and r.request_id=p_id;if found then return row.definition;end if;
 d:=exercise_definition_clean(p_definition);perform pg_advisory_xact_lock(hashtextextended(exercise_definition_signature(d),117));
 select *into row from common_exercises where signature=exercise_definition_signature(d);
 if not found then
  if exists(select 1 from common_exercises where id=p_id)then raise exception 'COMMON_EXERCISE_IMMUTABLE';end if;
  d:=d||jsonb_build_object('id',p_id,'libraryScope','common');insert into common_exercises values(p_id,d,exercise_definition_signature(d),u,now())returning *into row;
 end if;
 insert into exercise_creation_requests values(u,p_id,row.id)on conflict do nothing;return row.definition;
end$$;
create function public.exercise_library_personal_save(p_id text,p_definition jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare u uuid:=social_uid();d jsonb;origin text;existing personal_exercises;begin
 if p_id is null or length(p_id)not between 1 and 5000 then raise exception 'INVALID_EXERCISE_ID';end if;
 select *into existing from personal_exercises where id=p_id;if found and existing.owner_id<>u then raise exception 'EXERCISE_NOT_OWNED';end if;
 if exists(select 1 from common_exercises where id=p_id)then raise exception 'PERSONAL_ID_REQUIRED';end if;d:=exercise_definition_clean(p_definition);origin:=nullif(p_definition->>'originExerciseId','');
 if origin is not null and not exists(select 1 from common_exercises where id=origin)then
  select common_id into origin from exercise_creation_requests where owner_id=u and request_id=origin;
  if origin is null then raise exception 'ORIGIN_NOT_AVAILABLE';end if;
 end if;
 if existing.id is not null then origin:=existing.origin_id;end if;
 d:=d||jsonb_build_object('id',p_id,'libraryScope','personal','ownerId',u,'originExerciseId',origin,'archived',coalesce((p_definition->>'archived')::boolean,false))||case when existing.definition?'legacySource'then jsonb_build_object('legacySource',existing.definition->'legacySource')else '{}'::jsonb end;
 insert into personal_exercises values(p_id,u,origin,d,coalesce((p_definition->>'archived')::boolean,false),now())on conflict(id)do update set definition=excluded.definition,archived=excluded.archived,updated_at=excluded.updated_at where personal_exercises.owner_id=u;return d;
end$$;
create function public.exercise_library_list()returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select jsonb_build_object('common',coalesce((select jsonb_agg(definition order by definition->>'name',id)from common_exercises),'[]'::jsonb),'personal',coalesce((select jsonb_agg(definition order by definition->>'name',id)from personal_exercises where owner_id=auth.uid()),'[]'::jsonb))$$;

-- Register legacy definitions as links, not destructive replacements. Preserve all source IDs and series.
create function public.exercise_library_legacy_key(p jsonb)returns text language sql immutable set search_path=public,pg_temp as $$
 with parts as(select coalesce(p->>'id','')a,coalesce(p->>'name','')b,coalesce(p->>'equipment','')c,coalesce((select string_agg(x,','order by x)from jsonb_array_elements_text(case when jsonb_typeof(p->'muscles'->'primary')='array'then p->'muscles'->'primary'else '[]'::jsonb end)x),'')d,coalesce((select string_agg(x,','order by x)from jsonb_array_elements_text(case when jsonb_typeof(p->'muscles'->'secondary')='array'then p->'muscles'->'secondary'else '[]'::jsonb end)x),'')e)
 select md5(octet_length(a)||':'||a||'|'||octet_length(b)||':'||b||'|'||octet_length(c)||':'||c||'|'||octet_length(d)||':'||d||'|'||octet_length(e)||':'||e)from parts
$$;
create function public.exercise_library_link_legacy(p_owner uuid,p jsonb)returns text language plpgsql security definer set search_path=public,pg_temp as $$declare key text;common text;private_id text;d jsonb;mode text;measurement text;begin
 key:=exercise_library_legacy_key(p);common:=exercise_library_shared_match(p);
 if common is not null then insert into exercise_legacy_references values(p_owner,p->>'id',key,common,'common')on conflict do nothing;return common;end if;
 if exists(select 1 from personal_exercises where owner_id=p_owner and id=p->>'libraryId')then return p->>'libraryId';end if;
 private_id:='legacy:'||md5(p_owner::text||'|'||key);
 mode:=case when p->'loadIdentity'->>'lateralMode'in('one-side','both-sides','simultaneous-pair')then 'unilateral'else 'bilateral'end;
 measurement:=case when p->>'tracking'in('cardio','mobility')then 'duration'when p->>'equipment'='bodyweight'then 'bodyweight'else 'external_load'end;
 d:=jsonb_build_object('id',private_id,'name',left(coalesce(p->>'name','Exercice personnel'),200),'equipment',coalesce(p->>'equipment','unknown'),'loadMode',mode,'measurement',measurement,'muscles',case when jsonb_typeof(p->'muscles'->'primary')='array'and jsonb_typeof(p->'muscles'->'secondary')='array'then p->'muscles'else '{"primary":[],"secondary":[]}'::jsonb end,'libraryScope','personal','originExerciseId',null,'ownerId',p_owner,'familyId',coalesce(p->>'familyId','personal'),'familyLabel','Mes exercices','aliases',jsonb_build_array(p->>'name'),'legacySource',jsonb_build_object('id',p->>'id','name',p->>'name','equipment',p->>'equipment','muscles',p->'muscles'));
 if p->>'id'='Shoulder press'and exercise_library_normalize(p->>'name')~'^elevations? lateral'then d:=d||jsonb_build_object('equipment','unknown','muscles','{"primary":["side_delts"],"secondary":[]}'::jsonb,'familyLabel','Élévations latérales');end if;
 if measurement='duration'then d:=d||jsonb_build_object('tracking',p->>'tracking','counter','duration','isometric',coalesce(p->'isometric','false'::jsonb));end if;
 insert into personal_exercises values(private_id,p_owner,null,d,false,now())on conflict do nothing;
 insert into exercise_legacy_references values(p_owner,p->>'id',key,private_id,'personal')on conflict do nothing;return private_id;
end$$;
create function public.exercise_library_audit_snapshot(p_owner uuid,p_payload jsonb)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare e jsonb;begin
 for e in select value from jsonb_path_query(p_payload,'strict $.** ? (exists(@.id) && exists(@.name) && (exists(@.refs) || exists(@.sets) || exists(@.activityEntries)))','{}'::jsonb,true)value loop
  perform exercise_library_link_legacy(p_owner,e);
 end loop;
end$$;
-- Audit all users, including alternatives, all saved plans and custom exercises.
do $$declare d record;begin for d in select owner_id,payload from private_documents loop perform exercise_library_audit_snapshot(d.owner_id,d.payload);end loop;end$$;
revoke all on function public.exercise_library_legacy_key(jsonb),public.exercise_definition_signature(jsonb),public.exercise_definition_clean(jsonb),public.exercise_library_shared_match(jsonb),public.exercise_library_link_legacy(uuid,jsonb),public.exercise_library_audit_snapshot(uuid,jsonb),public.exercise_library_create(text,jsonb),public.exercise_library_personal_save(text,jsonb),public.exercise_library_list()from public,anon,authenticated;
grant execute on function public.exercise_library_list()to anon,authenticated;
grant execute on function public.exercise_library_create(text,jsonb),public.exercise_library_personal_save(text,jsonb)to authenticated;
create function public.exercise_library_capabilities()returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select jsonb_build_object('version',1,'loadProtocol','elan-2','privateCopies',true,'commonCount',(select count(*)from common_exercises))$$;
revoke all on function public.exercise_library_capabilities()from public;
grant execute on function public.exercise_library_capabilities()to anon,authenticated;
notify pgrst,'reload schema';
commit;
